{
  "achados": [
    {
      "titulo": "Creme de leite improvisado",
      "categoria": "substituicao",
      "texto": "200 ml de creme de leite podem ser aproximados por 150 ml de leite integral com 50 g de manteiga derretida. Funciona para molhos quentes, não funciona para chantilly — bater exige a gordura já emulsionada do creme.",
      "fonte": "Harold McGee, On Food and Cooking, cap. 1",
      "recuperado_por": "hibrida+rerank"
    },
    {
      "titulo": "Quanto tempo o preparo dura na geladeira",
      "categoria": "conservacao",
      "texto": "Preparo cozido e refrigerado a 4 °C ou menos dura de 3 a 4 dias com segurança. O resfriamento precisa ser rápido: do cozimento até 21 °C em até 2 horas, e até 4 °C em mais 4 horas. Preparo que fica mais de 2 horas entre 5 °C e 60 °C entra na zona de perigo e não deve ser vendido.",
      "fonte": "ANVISA RDC 216/2004 e FDA Food Code",
      "recuperado_por": "hibrida+rerank"
    },
    {
      "titulo": "Leite líquido a partir de leite em pó",
      "categoria": "substituicao",
      "texto": "1 litro de leite líquido equivale a aproximadamente 130 g de leite em pó integral dissolvidos em 900 ml de água morna. É uma troca relevante para custo: leite em pó costuma sair mais barato por litro reconstituído e dura muito mais na despensa.",
      "fonte": "tabela de reconstituição da embalagem padrão",
      "recuperado_por": "hibrida+rerank"
    },
    {
      "titulo": "O que o molho béchamel exige",
      "categoria": "tecnica",
      "texto": "Béchamel é um roux de manteiga e farinha em partes iguais, cozido sem dourar, ao qual se acrescenta leite morno aos poucos mexendo sempre. Exige fogo baixo constante e atenção contínua por 8 a 10 minutos. Quem não domina, empelota — e massa empelotada não é recuperável sem peneirar.",
      "fonte": "Auguste Escoffier, Le Guide Culinaire",
      "recuperado_por": "hibrida+rerank"
    }
  ],
  "observacao": "cite a fonte ao repassar: ela cozinha há mais tempo que nós"
}

